-- Dungeon Master's Guide II source-backed rules catalog.
-- Mechanical summaries are intentionally concise; the supplied sourcebook remains authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg2-3.5','dungeon-masters-guide-ii-3-5','Dungeon Master''s Guide II','DMG II',
        'Wizards of the Coast','dnd','3.5','D&D v.3.5 Dungeon Master''s Guide II: expanded DM procedures, encounter subsystems, campaign tools, character teamwork systems, and magic-item options.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,summary,tags,mechanics) AS (VALUES
  ('dmg2-adventure-pacing','Adventure Pacing','37','adventures','guidance',0,1,NULL,NULL,'Alternate pressure and recovery, escalate toward important scenes, and shorten or rearrange material when momentum is sagging.','["pacing","adventures"]','{}'),
  ('dmg2-published-adventure-adaptation','Using and Adapting Published Adventures','38','adventures','guidance',0,1,NULL,NULL,'Reuse useful material, link it to existing campaign elements, make simple fixes for party differences, and change direction when players invalidate assumptions.','["published-adventures"]','{}'),
  ('dmg2-expanded-traps','Expanded Trap Design','40','traps','subsystem',1,0,'dmg-designing-traps',NULL,'Supplement core trap design with multi-stage, environmental, summoning, weapon, fey-ring, and spell-turret traps whose CR reflects both mechanical danger and escape constraints.','["traps","expanded"]','{}'),
  ('dmg2-fey-ring-traps','Fey Ring Traps','43','traps','table',1,0,'dmg2-expanded-traps',NULL,'Fey rings are magical location-triggered traps with minor, moderate, and major versions, each using a random spell effect and corresponding save DC/CR.','["traps","fey"]','{"minor":{"cr":4,"save_dc":13},"moderate":{"cr":7,"save_dc":17},"major":{"cr":10,"save_dc":22},"search_dc":20,"disable_dc":30}'),
  ('dmg2-fire-summoning-trap','Fire Summoning Traps','43','traps','subsystem',1,0,'dmg2-expanded-traps',NULL,'A fire-summoning trap combines ongoing burning gas with a delayed summoned fire elemental; disabling the shared mechanism prevents both elements.','["traps","fire","summoning"]','{}'),
  ('dmg2-archetypal-locations','Archetypal Encounter Locations','47','encounters','guidance',0,1,NULL,NULL,'Encounter locations can carry their own movement, visibility, hazard, and tactical rules rather than serving as featureless rooms.','["encounters","terrain"]','{}'),
  ('dmg2-battle-in-sky','Battle in the Sky','47','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'Aerial encounters emphasize falling, altitude, maneuverability, three-dimensional positions, and limited stable surfaces.','["flight","encounters"]','{}'),
  ('dmg2-burning-building','Burning Building Encounter','48','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'A burning structure combines spreading fire, smoke, collapsing construction, rescue objectives, and time pressure.','["fire","encounters"]','{}'),
  ('dmg2-evil-crypt','Evil Crypt Encounter','50','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'Crypt encounters combine confined terrain, funerary features, undead themes, darkness, and magical/environmental threats.','["crypt","encounters"]','{}'),
  ('dmg2-flooding-dungeon','Flooding Dungeon Encounter','51','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'Rising water changes movement, escape routes, drowning risk, visibility, and encounter timing as the dungeon fills.','["water","encounters"]','{}'),
  ('dmg2-ice-bridge','Ice Bridge Encounter','52','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'An ice bridge combines narrow footing, slippery terrain, falling danger, and potentially breakable surfaces.','["ice","encounters"]','{}'),
  ('dmg2-lava-encounter','Lava Encounter','53','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'Lava encounters combine core lava damage with constrained footing, heat, jumping, falling, and forced-movement risks.','["lava","encounters"]','{}'),
  ('dmg2-restrictive-tunnels','Restrictive Tunnel Encounter','55','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'Very tight tunnels alter movement, weapon use, formation, line of sight, and the ability of larger creatures to maneuver.','["tunnels","encounters"]','{}'),
  ('dmg2-treetop-village','Treetop Village Encounter','56','encounters','subsystem',1,0,'dmg2-archetypal-locations',NULL,'Treetop encounters use vertical movement, narrow platforms, falls, ropes/bridges, and line-of-sight differences between elevations.','["vertical","encounters"]','{}'),
  ('dmg2-chase','Dramatic Chase','57','encounters','subsystem',1,0,'dmg-evasion-pursuit-short',NULL,'Resolve a chase by comparing speeds each round; the pursuer closes by the speed difference when faster, while terrain, obstacles, checks, and tactical choices can change the gap.','["chase"]','{"gap_change":"pursuer_speed - quarry_speed","interval":"round"}'),
  ('dmg2-swinging-combat','Swinging-Rope Combat','56','movement','rule',1,0,NULL,NULL,'Swinging movement uses Strength/Climb checks; a character can attack at the end of a qualifying swing with a one-handed weapon and can gain charge/higher-ground benefits subject to the subsystem''s penalties.','["swinging","movement","combat"]','{"climb_dc_unsknotted":20,"climb_dc_knotted":15,"one_handed_swing_penalty":-2}'),
  ('dmg2-crowds','Crowds','58','encounters','subsystem',1,0,NULL,NULL,'Dense crowds affect movement, visibility, pursuit, social checks, and the ease of losing or finding individuals.','["crowds","urban"]','{}'),
  ('dmg2-mobs','Mobs','59','encounters','subsystem',1,0,NULL,NULL,'A mob represents a large mass of creatures as one 30-HD entity with special space, movement, attack, trample, and anatomy rules.','["mob","mass-combat"]','{"hit_dice":30,"space_feet":20,"reach_feet":0}'),
  ('dmg2-mob-space-movement','Mob Space and Movement','59','encounters','rule',1,0,'dmg2-mobs',NULL,'A mob occupies a 20-foot-square area, has 0-foot reach, enters opponents'' spaces to attack, and can move through occupied squares while provoking attacks of opportunity as specified.','["mob","movement"]','{"space_feet":20,"reach_feet":0}'),
  ('dmg2-mob-attacks','Mob Attacks','59','encounters','rule',1,0,'dmg2-mobs',NULL,'Mob attacks ignore concealment and cover; they are nonmagical unless the base creature''s attacks are magical, and damage reduction applies normally.','["mob","combat"]','{"ignores_cover":true,"ignores_concealment":true}'),
  ('dmg2-mob-trample','Mob Trample','60','encounters','rule',1,0,'dmg2-mobs',NULL,'A mob moving over a creature without ending in its square can trample for 2d6 + 1-1/2 Strength modifier; victim chooses an attack of opportunity or Reflex save DC 25 + mob Strength modifier for half.','["mob","trample"]','{"damage":"2d6 + 1.5 * Strength modifier","reflex_dc":"25 + Strength modifier","save_effect":"half"}'),
  ('dmg2-mob-anatomy','Mob Anatomy','60','encounters','rule',1,0,'dmg2-mobs',NULL,'A mob has no clear anatomy: no critical hits or sneak attacks, and it cannot be flanked, tripped, grappled, or bull rushed.','["mob"]','{"immune":["critical_hits","sneak_attack","flanking","trip","grapple","bull_rush"]}'),
  ('dmg2-mob-single-target-effects','Single-Target Effects against Mobs','60','encounters','rule',1,0,'dmg2-mobs',NULL,'Each specific component creature incapacitated by a single-target effect gives the mob two special negative levels; the mob breaks up when these equal its Hit Dice, and these levels are not negative energy.','["mob"]','{"negative_levels_per_creature":2,"breakup_at_negative_levels":"mob_hit_dice","negative_energy":false}'),
  ('dmg2-minis-encounter-building','Miniatures and Encounter Building','61','encounters','guidance',0,1,NULL,NULL,'Use miniature positioning, terrain, objectives, creature roles, and starting conditions to make tactical encounters varied and readable.','["miniatures","encounters"]','{}'),
  ('dmg2-alignment-encounters','Alignment-Based Encounters','62','encounters','guidance',0,1,NULL,NULL,'Alignment can shape motives, alliances, reactions, and objective conflicts without forcing every aligned creature into identical behavior.','["alignment","encounters"]','{}'),
  ('dmg2-using-terrain','Using Terrain in Encounters','62','encounters','guidance',0,1,NULL,NULL,'Terrain should matter mechanically through cover, concealment, movement, elevation, hazards, bottlenecks, and interactable features.','["terrain","encounters"]','{}'),
  ('dmg2-making-it-fair','Making Encounters Fair','62','encounters','guidance',0,1,NULL,NULL,'Communicate unusual dangers through clues and provide meaningful choices; fairness does not require every fight to be equal but does require usable information and consistent adjudication.','["encounters","fairness"]','{}'),
  ('dmg2-battle-grid-terrain','Battle Grid Terrain','63','encounters','table',1,0,NULL,NULL,'Expanded battle-grid terrain gives movement, cover, concealment, climb, balance, and tactical properties to common encounter features.','["grid","terrain"]','{}'),
  ('dmg2-encounter-tables','Expanded Encounter Tables','65','encounters','table',1,0,NULL,NULL,'Location-specific encounter tables provide ready encounters for unusual environments and urban/adventure situations.','["random-encounters"]','{}'),
  ('dmg2-sample-treasure-hoards','Sample Treasure Hoards','71','treasure','table',1,0,NULL,NULL,'Prebuilt hoards demonstrate how to bundle coins, valuables, and magic items into memorable treasure packages of different values.','["treasure"]','{}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dmg2-3.5-rule-' || d.slug, 'dmg2-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,d.parent_slug,d.supersedes_slug,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r
  WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
